using System;
using System.Collections.Concurrent;
using System.IO;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace FileProcessor
{
    public class SafePathValidator
    {
        private static readonly string BaseDirectory = Path.GetFullPath("/app/data");

        public static string NormalizePath(string input)
        {
            // Normalize Unicode to NFKC form for consistent comparison
            string normalized = input.Normalize(NormalizationForm.FormKC);
            return normalized;
        }

        public static bool IsPathSafe(string requestedPath)
        {
            string fullPath = Path.GetFullPath(Path.Combine(BaseDirectory, requestedPath));
            return fullPath.StartsWith(BaseDirectory, StringComparison.Ordinal);
        }
    }

    public class FileOperationQueue
    {
        private readonly ConcurrentQueue<FileOperation> _queue = new();
        private readonly CancellationTokenSource _cts = new();
        private readonly SemaphoreSlim _signal = new(0);
        private Task _processorTask;

        public void Start()
        {
            _processorTask = Task.Run(() => ProcessLoop(_cts.Token));
        }

        public void EnqueueOperation(string path, string content)
        {
            var op = new FileOperation
            {
                RawPath = path,
                Content = content,
                EnqueuedAt = DateTime.UtcNow
            };
            _queue.Enqueue(op);
            _signal.Release();
        }

        private async Task ProcessLoop(CancellationToken ct)
        {
            while (!ct.IsCancellationRequested)
            {
                await _signal.WaitAsync(ct);
                if (_queue.TryDequeue(out var operation))
                {
                    await ExecuteOperation(operation);
                }
            }
            // Graceful shutdown: drain remaining operations
            await DrainQueue();
        }

        private async Task DrainQueue()
        {
            while (_queue.TryDequeue(out var operation))
            {
                await ExecuteOperation(operation);
            }
        }

        private async Task ExecuteOperation(FileOperation operation)
        {
            // Phase 1: Validate the normalized path
            string normalizedInput = SafePathValidator.NormalizePath(operation.RawPath);

            if (!SafePathValidator.IsPathSafe(normalizedInput))
            {
                Console.WriteLine($"[BLOCKED] Path traversal attempt: {operation.RawPath}");
                return;
            }

            // Phase 2: Build final path using the SAME normalized form
            string finalPath = BuildFinalPath(normalizedInput);

            // Phase 3: Write content
            string directory = Path.GetDirectoryName(finalPath);
            if (!Directory.Exists(directory))
                Directory.CreateDirectory(directory);

            await File.WriteAllTextAsync(finalPath, operation.Content);
            Console.WriteLine($"[OK] Written to: {finalPath}");
        }

        private string BuildFinalPath(string normalizedPath)
        {
            // Use the already-NFKC-normalized path consistently
            return Path.GetFullPath(Path.Combine("/app/data", normalizedPath));
        }

        public async Task ShutdownAsync()
        {
            _cts.Cancel();
            if (_processorTask != null)
                await _processorTask;
        }
    }

    public class FileOperation
    {
        public string RawPath { get; set; }
        public string Content { get; set; }
        public DateTime EnqueuedAt { get; set; }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var queue = new FileOperationQueue();
            queue.Start();

            Console.CancelKeyPress += async (s, e) =>
            {
                e.Cancel = true;
                Console.WriteLine("Shutting down gracefully...");
                await queue.ShutdownAsync();
            };

            Console.WriteLine("File Processor CLI - Enter 'path|content' or 'quit'");

            while (true)
            {
                string line = Console.ReadLine();
                if (line == null || line.Equals("quit", StringComparison.OrdinalIgnoreCase))
                    break;

                var parts = line.Split('|', 2);
                if (parts.Length == 2)
                {
                    queue.EnqueueOperation(parts[0].Trim(), parts[1].Trim());
                }
                else
                {
                    Console.WriteLine("Format: path|content");
                }
            }

            await queue.ShutdownAsync();
        }
    }
}
